import type { Bounds, Vec2 } from '../geometry/types'

/**
 * Level JSON in `public/levels/`, generated by `npm run levels` (`scripts/import-ipe.ts`) from the
 * Unity level files in `legacy/levels/`.
 *
 * Coordinates use the SVG convention (y points down). IPE levels are centred on the origin and scaled
 * so the larger side of the bounding box has the size the Unity version used for that game
 * ({@link LEVEL_SIZE}); the five Unity `.asset` levels were made by hand in those units and are only
 * mirrored (y flipped), not scaled.
 */
export const LEVEL_FORMAT_VERSION = 1

export type Collection =
  'art-gallery' | 'kings-taxes/mst' | 'kings-taxes/spanner' | 'kings-taxes/tsp' | 'divide' | 'convex-hull'

export const COLLECTIONS: readonly Collection[] = [
  'art-gallery',
  'kings-taxes/mst',
  'kings-taxes/spanner',
  'kings-taxes/tsp',
  'divide',
  'convex-hull',
]

/** Larger side of the bounding box of an imported IPE level, per collection (as in Unity). */
export const LEVEL_SIZE: Record<Collection, number> = {
  'art-gallery': 9,
  'kings-taxes/mst': 6,
  'kings-taxes/spanner': 6,
  'kings-taxes/tsp': 6,
  divide: 5,
  'convex-hull': 6,
}

interface LevelBase {
  /** `<collection>/<name>`, also the path of the file below `public/levels/` without `.json`. */
  id: string
  collection: Collection
  /** File name without extension, e.g. `agLevel4_8`. */
  name: string
  /** Level number from the file name (the Unity scene order). */
  number: number
  /** Source file, relative to the repository root. */
  source: string
  bounds: Bounds
}

/**
 * Art gallery ("Licht ins Verlies"). The outer boundary has positive signed area (shoelace formula on
 * the stored coordinates, so it runs clockwise on screen), holes negative. Rings are not closed (the
 * last vertex is not repeated).
 */
export interface ArtGalleryLevel extends LevelBase {
  collection: 'art-gallery'
  /** Number of torches the level designer allowed (k); not a proven minimum. */
  torches: number
  outer: Vec2[]
  holes: Vec2[][]
}

/** Kings Taxes (MST, t-spanner, TSP): settlements; villages and castles differ only in look. */
export interface KingsTaxesLevel extends LevelBase {
  collection: 'kings-taxes/mst' | 'kings-taxes/spanner' | 'kings-taxes/tsp'
  /** Spanner ratio t (spanner levels only). */
  ratio?: number
  villages: Vec2[]
  castles: Vec2[]
}

/** Divide (ham sandwich): three kinds of soldiers, each with an even count. */
export interface DivideLevel extends LevelBase {
  collection: 'divide'
  /** Allowed swaps. */
  swaps: number
  spearmen: Vec2[]
  archers: Vec2[]
  mages: Vec2[]
}

/** Convex hull tutorial levels. */
export interface ConvexHullLevel extends LevelBase {
  collection: 'convex-hull'
  points: Vec2[]
}

export type Level = ArtGalleryLevel | KingsTaxesLevel | DivideLevel | ConvexHullLevel

/** `public/levels/index.json`: level ids per collection, in the Unity scene order. */
export interface LevelIndex {
  version: typeof LEVEL_FORMAT_VERSION
  collections: Record<Collection, string[]>
}
